// ext/fast_math/fast_math.c
#include <ruby.h>

static VALUE fast_sum(VALUE self, VALUE ary) {
  long total = 0;
  for (long i = 0; i < RARRAY_LEN(ary); i++) {
    total += NUM2LONG(rb_ary_entry(ary, i));
  }
  return LONG2NUM(total);
}

void Init_fast_math(void) {
  VALUE mod = rb_define_module("FastMath");
  rb_define_module_function(mod, "sum", fast_sum, 1);
}
